"use client";

import { UseFormRegister, UseFormSetValue, UseFormWatch } from "react-hook-form";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { PropertiesInput } from "@/validators/propertiesSchema";
import { useLanguage } from "@/contexts/LanguageContext";

interface SeoSectionProps {
  register: UseFormRegister<PropertiesInput>;
  setValue?: UseFormSetValue<PropertiesInput>;
  watch?: UseFormWatch<PropertiesInput>;
}

export default function SeoSection({ register, setValue, watch }: SeoSectionProps) {
  const { t, language } = useLanguage();
  const isAr = language === "ar";

  const handleGenerateSlug = () => {
    if (!setValue || !watch) return;
    const propertyName = watch("property_name") || "";
    if (!propertyName) return;

    const generatedSlug = propertyName
      .toLowerCase()
      .trim()
      .replace(/[^\w\s-]/g, "")
      .replace(/[\s_-]+/g, "-")
      .replace(/^-+|-+$/g, "");

    setValue("slug", generatedSlug, { shouldValidate: true });
  };

  return (
    <div className="bg-white dark:bg-neutral-900 rounded-xl border border-gray-200 dark:border-neutral-800 p-5 sm:p-6 space-y-3.5 shadow-2xs">
      <div>
        <h2 className="text-sm sm:text-base font-semibold text-gray-900 dark:text-gray-100">
          {isAr ? "تحسين محركات البحث (SEO)" : (t("properties.create.seo.title") || "Search Engine Optimization (SEO)")}
        </h2>
      </div>

      <div className="space-y-3.5">
        <div>
          <Label
            htmlFor="slug"
            className="text-xs font-semibold text-gray-700 dark:text-gray-300"
          >
            {isAr ? "الرابط المخصص (Slug)" : (t("properties.create.seo.slug") || "Slug")}
          </Label>
          <div className="flex items-center gap-2 mt-1">
            <div className="relative flex-1 flex items-center rounded-md border border-input dark:border-neutral-700 bg-white dark:bg-neutral-950 h-9 shadow-2xs focus-within:ring-1 focus-within:ring-ring">
              <span className="pl-3 pr-2 text-xs text-gray-400 dark:text-gray-500 font-mono select-none">
                /
              </span>
              <input
                id="slug"
                {...register("slug")}
                placeholder={t("properties.create.seo.slugPlaceholder") || "my-property"}
                className="w-full bg-transparent py-1.5 pr-3 text-xs outline-none placeholder:text-muted-foreground dark:text-gray-100"
              />
            </div>
            <Button
              type="button"
              variant="outline"
              onClick={handleGenerateSlug}
              className="border-[#008081] dark:border-teal-500 text-[#008081] dark:text-teal-400 hover:bg-teal-50 dark:hover:bg-teal-950/40 text-xs px-3.5 h-9 shadow-2xs shrink-0 font-medium"
            >
              {isAr ? "توليد" : (t("properties.create.seo.generate") || "Generate")}
            </Button>
          </div>
          <p className="text-[11px] text-gray-500 dark:text-gray-400 mt-1">
            {isAr ? "يتم إنشاؤه تلقائياً من الاسم؛ يمكنك تعديله." : (t("properties.create.seo.slugHelp") || "Auto-generated from the name; you can edit it.")}
          </p>
        </div>

        {/* Meta Title */}
        <div>
          <Label
            htmlFor="meta_title"
            className="text-xs font-semibold text-gray-700 dark:text-gray-300"
          >
            {isAr ? "عنوان الميتا (Meta Title)" : (t("properties.create.seo.metaTitle") || "Meta Title")}
          </Label>
          <Input
            id="meta_title"
            {...register("meta_title")}
            placeholder={isAr ? "عنوان الصفحة لمحركات البحث" : (t("properties.create.seo.metaTitlePlaceholder") || "Page title for search engines")}
            className="mt-1 h-9 text-xs dark:bg-neutral-950 dark:border-neutral-700"
          />
        </div>

        {/* Meta Description */}
        <div>
          <div className="flex items-center justify-between mb-1">
            <Label
              htmlFor="meta_description"
              className="text-xs font-semibold text-gray-700 dark:text-gray-300"
            >
              {isAr ? "وصف الميتا (Meta Description)" : (t("properties.create.seo.metaDescription") || "Meta Description")}
            </Label>
            <span className="text-[11px] text-gray-400 dark:text-gray-500">
              {isAr ? "وصف مختصر يظهر في نتائج البحث" : "Short description shown in search results"}
            </span>
          </div>
          <Textarea
            id="meta_description"
            {...register("meta_description")}
            placeholder={isAr ? "اكتب وصف الميتا هنا" : (t("properties.create.seo.metaDescriptionPlaceholder") || "Short description shown in search results")}
            rows={2}
            className="min-h-[70px] text-xs resize-none bg-white dark:bg-neutral-950 border-input dark:border-neutral-700 dark:text-gray-100"
          />
        </div>
      </div>
    </div>
  );
}
