"use client";

import { UseFormRegister, UseFormSetValue, UseFormWatch } from "react-hook-form";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { PropertiesInput } from "@/validators/propertiesSchema";
import { useLanguage } from "@/contexts/LanguageContext";
import SeoSection from "../SeoSection";

interface LicensesTabProps {
  register: UseFormRegister<PropertiesInput>;
  setValue?: UseFormSetValue<PropertiesInput>;
  watch?: UseFormWatch<PropertiesInput>;
}

export default function LicensesTab({ register, setValue, watch }: LicensesTabProps) {
  const { t } = useLanguage();

  return (
    <div className="space-y-4">
      <div className="bg-white dark:bg-neutral-900 rounded-xl border border-gray-200 dark:border-neutral-800 p-5 sm:p-6 space-y-4 shadow-2xs">
        <div>
          <h2 className="text-sm sm:text-base font-semibold text-gray-900 dark:text-gray-100">
            {t("properties.create.license.title") || "Government Compliance & Licenses"}
          </h2>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
            {t("properties.create.license.subtitle") || "DLD permits, QR verification codes, agent and broker credentials."}
          </p>
        </div>

        {/* 3 inputs per row grid */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <Label htmlFor="broker_license" className="text-xs font-semibold text-gray-700 dark:text-gray-300">
              {t("properties.create.license.brokerLicense") || "Broker License Number"}
            </Label>
            <Input
              id="broker_license"
              {...register("broker_license")}
              placeholder={t("properties.create.license.brokerLicense") || "e.g., 123456"}
              className="mt-1 h-9 text-xs"
            />
          </div>

          <div>
            <Label htmlFor="agent_license" className="text-xs font-semibold text-gray-700 dark:text-gray-300">
              {t("properties.create.license.agentLicense") || "Agent License Number"}
            </Label>
            <Input
              id="agent_license"
              {...register("agent_license")}
              placeholder={t("properties.create.license.agentLicense") || "e.g., 654321"}
              className="mt-1 h-9 text-xs"
            />
          </div>

          <div>
            <Label htmlFor="dld_permit_number" className="text-xs font-semibold text-gray-700 dark:text-gray-300">
              {t("properties.create.license.dldPermitNumber") || "DLD Permit Number / Trakheesi"}
            </Label>
            <Input
              id="dld_permit_number"
              {...register("dld_permit_number")}
              placeholder={t("properties.create.license.dldPermitNumber") || "e.g., DLD-7890"}
              className="mt-1 h-9 text-xs"
            />
          </div>

          <div>
            <Label htmlFor="dld_barcode" className="text-xs font-semibold text-gray-700 dark:text-gray-300">
              {t("properties.create.license.dldBarcode") || "DLD QR Code / Barcode"}
            </Label>
            <Input
              id="dld_barcode"
              {...register("dld_barcode")}
              placeholder={t("properties.create.license.dldBarcode") || "e.g., BC-123456"}
              className="mt-1 h-9 text-xs"
            />
          </div>

          <div>
            <Label htmlFor="reference_listed" className="text-xs font-semibold text-gray-700 dark:text-gray-300">
              {t("properties.create.license.referenceListed") || "Internal Reference Code"}
            </Label>
            <Input
              id="reference_listed"
              {...register("reference_listed")}
              placeholder={t("properties.create.license.referenceListed") || "e.g., REF-2024-001"}
              className="mt-1 h-9 text-xs"
            />
          </div>

          <div>
            <Label htmlFor="parking_spaces" className="text-xs font-semibold text-gray-700 dark:text-gray-300">
              {t("properties.create.license.parkingSpaces") || "Parking Spaces"}
            </Label>
            <Input
              id="parking_spaces"
              type="number"
              {...register("parking_spaces", { valueAsNumber: true })}
              placeholder={t("properties.create.license.parkingSpacesPlaceholder") || "e.g., 1 or 2"}
              className="mt-1 h-9 text-xs"
            />
          </div>
        </div>
      </div>

      <SeoSection register={register} setValue={setValue} watch={watch} />
    </div>
  );
}
